import { createServer } from "node:http";

const server = createServer(handler);
server.listen(3000);

let closing = false;
async function shutdown(signal: string) {
  if (closing) return;            // 第二次信号去重
  closing = true;
  console.log(`got ${signal}`);

  // 1) 停止接新连接，等待存量请求完成
  server.close(() => {
    console.log("closed-clean");
    process.exit(0);
  });

